import {
    FloatingFocusManager,
    useDismiss,
    useFloating,
    useInteractions,
    useTransitionStatus,
} from "@floating-ui/react";
import { CrossIcon } from "@lifesg/react-icons/cross";
import clsx from "clsx";
import { useEffect, useRef, useState } from "react";
import { useResizeDetector } from "react-resize-detector";

import { Overlay } from "../overlay";
import { ClickableIcon } from "../shared/clickable-icon";
import {
    Breakpoint,
    parsePxOrRemValue,
    useResolvedBreakpointToken,
} from "../theme";
import { Typography } from "../typography";
import { useId } from "../util";
import * as styles from "./drawer.styles";
import type { DrawerProps } from "./types";

// @catalog
/**
 * A slide-in panel that overlays the page content.
 *
 * Use `Drawer` to surface supplementary content or navigation options without
 * navigating away from the current page. Focus is trapped inside the dialog
 * while it is open and returns to the triggering element on close.
 * @keywords overlay, panel, side panel, tray
 */
export const Drawer = ({
    children,
    heading,
    show,
    onClose,
    onOverlayClick,
    customCallToAction,
    className,
    ...otherProps
}: DrawerProps) => {
    // =========================================================================
    // CONST, STATE, REFS
    // =========================================================================
    const [showOverlay, setShowOverlay] = useState(show);
    // vertical centre of the heading, used to align the (last-in-DOM,
    // absolutely positioned) close button with it
    const [closeButtonTop, setCloseButtonTop] = useState<number>();
    const id = useId();
    const initialFocusRef = useRef<HTMLHeadingElement>(null);
    // Observe the header (whose size tracks the drawer's actual width, which
    // consumers may override) to drive layout in one pass: the width decides
    // call-to-action stacking, and each resize re-centres the close button on
    // the heading. offsetTop/offsetHeight are relative to the drawer (the
    // positioned ancestor), so they share the close button's coordinate space.
    const { width: headerWidth, ref: headerRef } =
        useResizeDetector<HTMLDivElement>({
            refreshMode: "throttle",
            refreshRate: 300,
            onResize: () => {
                const headingEl = initialFocusRef.current;
                if (headingEl) {
                    setCloseButtonTop(
                        headingEl.offsetTop + headingEl.offsetHeight / 2
                    );
                }
            },
        });
    // stack the call-to-action below the heading once the drawer is too narrow
    // to fit both on one line
    const stackWidth = parsePxOrRemValue(
        useResolvedBreakpointToken(Breakpoint["sm-max"])
    );
    const stackCallToAction =
        headerWidth !== undefined && headerWidth <= stackWidth;

    // =========================================================================
    // FLOATING UI CONFIG
    // =========================================================================
    const { context, refs } = useFloating({
        open: show,
        onOpenChange: (open) => {
            if (!open && onClose) {
                onClose();
            }
        },
    });

    const dismiss = useDismiss(context, {
        escapeKey: true,
        outsidePress: false, // defer to Overlay click
    });

    const { getFloatingProps } = useInteractions([dismiss]);

    const { isMounted, status } = useTransitionStatus(context, {
        duration: 800,
    });

    // =========================================================================
    // EFFECTS
    // =========================================================================
    useEffect(() => {
        if (!show) {
            const timer = setTimeout(() => setShowOverlay(false), 800);
            return () => clearTimeout(timer);
        } else {
            setShowOverlay(true);
        }
    }, [show]);

    // =========================================================================
    // EVENT HANDLERS
    // =========================================================================
    const handleDialogVisibility = (e: React.TransitionEvent) => {
        if (e.propertyName === "visibility" && show) {
            // focus the first element so that the screenreader enters the dialog
            initialFocusRef.current?.focus();
        }
    };

    // =========================================================================
    // RENDER FUNCTIONS
    // =========================================================================
    return (
        <Overlay
            show={showOverlay}
            enableOverlayClick
            onOverlayClick={onOverlayClick}
        >
            {isMounted ? (
                <FloatingFocusManager
                    context={context}
                    initialFocus={-1}
                    returnFocus={true}
                >
                    <div
                        ref={refs.setFloating}
                        data-status={status}
                        data-testid="drawer"
                        aria-modal
                        role="dialog"
                        aria-labelledby={id}
                        onTransitionEnd={handleDialogVisibility}
                        className={clsx(styles.container, className)}
                        {...getFloatingProps()}
                        {...otherProps}
                    >
                        <div
                            ref={headerRef}
                            className={clsx(
                                styles.header,
                                stackCallToAction && styles.headerStacked
                            )}
                        >
                            <Typography.HeadingMD
                                as="h2"
                                className={styles.heading}
                                id={id}
                                ref={initialFocusRef}
                                tabIndex={-1}
                                weight="bold"
                            >
                                {heading}
                            </Typography.HeadingMD>
                            {customCallToAction ? (
                                <div
                                    className={clsx(
                                        styles.callToAction,
                                        stackCallToAction &&
                                            styles.callToActionStacked
                                    )}
                                >
                                    {customCallToAction}
                                </div>
                            ) : null}
                        </div>
                        <div className={styles.content}>{children}</div>
                        {/* Rendered last so assistive tech reaches the heading
                            and content before the close button; centred against
                            the header via its measured height. */}
                        <ClickableIcon
                            aria-label="Close drawer"
                            onClick={onClose}
                            focusHighlight={false}
                            className={styles.closeButton}
                            style={
                                closeButtonTop !== undefined
                                    ? {
                                          top: closeButtonTop,
                                          transform: "translateY(-50%)",
                                      }
                                    : undefined
                            }
                        >
                            <CrossIcon aria-hidden />
                        </ClickableIcon>
                    </div>
                </FloatingFocusManager>
            ) : undefined}
        </Overlay>
    );
};
